try{$pdo=new PDO('mysql:host='.$value('DB_HOST','127.0.0.1').';port='.$value('DB_PORT','3306').';dbname='.$value('DB_NAME').';charset=utf8mb4',$value('DB_USER'),$value('DB_PASSWORD'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$query=$pdo->prepare('SELECT COLUMN_NAME FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=?');$missing=[];foreach($required as$t=>$cols){$query->execute([$t]);$present=$query->fetchAll(PDO::FETCH_COLUMN);foreach(array_diff($cols,$present)as$c)$missing[]=$t.'.'.$c;}
